/**
 * Cron route: /api/cron/generate-tour
 *
 * IMPORTANT — SERVERLESS / BROWSER LIMITATION:
 * The product tour is generated by Playwright/Chromium (see scripts/generate-tour.ts).
 * Playwright CANNOT run inside Vercel serverless functions — there is no Chromium
 * binary and no way to launch one in that environment. Therefore this route must
 * NEVER attempt to launch a browser.
 *
 * Instead this route is a thin, honest trigger:
 *   (a) If TOUR_TRIGGER_WEBHOOK_URL is set (e.g. a GitHub Actions repository_dispatch
 *       endpoint or an external browser-capable runner), POST to it and return
 *       { triggered: true }.
 *   (b) Otherwise, return a clear message (status 200) explaining the tour must be
 *       generated via `npm run generate-tour` in a browser-capable environment.
 *
 * This route is built to never 500 — all failures are caught and reported as JSON.
 */

import { NextRequest, NextResponse } from 'next/server';
import { createServerClient } from '@supabase/ssr';
import { isAdminUser } from '@/lib/planConfig';
import { checkCronAuth } from '@/lib/cronAuth';

export const dynamic = 'force-dynamic';

// Cron: Bearer CRON_SECRET (no hardcoded fallback, no x-cron-secret).
// Admins can also trigger it from /admin/tour with their session.
async function authorize(req: NextRequest): Promise<boolean> {
  if (checkCronAuth(req.headers.get('authorization')) === 'ok') {
    return true;
  }

  try {
    const supabase = createServerClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
      { cookies: { getAll: () => req.cookies.getAll(), setAll: () => {} } }
    );
    const { data: { user } } = await supabase.auth.getUser();
    return isAdminUser(user?.email);
  } catch {
    return false;
  }
}

async function handle(req: NextRequest): Promise<NextResponse> {
  try {
    if (!(await authorize(req))) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const webhookUrl = process.env.TOUR_TRIGGER_WEBHOOK_URL;

    // (a) Delegate to an external browser-capable runner if configured.
    if (webhookUrl) {
      try {
        const res = await fetch(webhookUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ event_type: 'generate-tour', source: 'vercel-cron' }),
        });
        return NextResponse.json({
          triggered: true,
          webhook_status: res.status,
          reason: 'Posted to TOUR_TRIGGER_WEBHOOK_URL to run Playwright generation externally.',
        });
      } catch (e) {
        // Even a webhook failure should not 500 the cron.
        return NextResponse.json({
          triggered: false,
          reason: `Failed to reach TOUR_TRIGGER_WEBHOOK_URL: ${String(e)}`,
        });
      }
    }

    // (b) No external trigger configured — explain the manual path.
    return NextResponse.json({
      triggered: false,
      reason:
        'Playwright/Chromium cannot run in Vercel serverless. Generate the tour by running ' +
        '`npm run generate-tour` in a browser-capable environment (local dev or CI/GitHub Actions), ' +
        'or set TOUR_TRIGGER_WEBHOOK_URL to an external runner so this cron can trigger it.',
    });
  } catch (e) {
    // Final safety net: never 500.
    return NextResponse.json({ triggered: false, reason: `Unexpected error: ${String(e)}` });
  }
}

export async function POST(req: NextRequest) {
  return handle(req);
}

export async function GET(req: NextRequest) {
  return handle(req);
}
